import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DirectionalLight, AmbientLight } = ctx.THREE;

  const visuals = config.intent?.visualSpec ?? {};
  const colors = visuals.colors ?? {};
  const items = config.textContent ?? visuals.textContent ?? [];
  const root = new Group();
  root.name = 'testimonial-panel';

  // ── Stage backdrop so the frame is never void
  const stageMat = new MeshBasicNodeMaterial();
  stageMat.colorNode = uniform(new Color(colors.background ?? '#0b0b10'));
  const stageGeo = new PlaneGeometry(7.2, 6);
  const stage = new Mesh(stageGeo, stageMat);
  stage.position.z = -2.5;
  root.add(stage);

  // ── Panel surface (PBR with engineered vertical gradient)
  const panelW = 3.4, panelH = 1.9;
  const topHex = colors.gradientStops?.[0]?.hex ?? '#1a1a22';
  const bottomHex = colors.gradientStops?.[1]?.hex ?? '#111116';

  const panelMat = new MeshPhysicalNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
    clearcoatRoughness: 0.5,
  });
  panelMat.colorNode = mix(uniform(new Color(bottomHex)), uniform(new Color(topHex)), uv().y);
  const panelGeo = new PlaneGeometry(panelW, panelH);
  const panel = new Mesh(panelGeo, panelMat);
  root.add(panel);

  // ── Hairline border (0.006u stroke via slightly larger backdrop plane)
  const borderMat = new MeshBasicNodeMaterial();
  borderMat.colorNode = uniform(new Color('#26262f'));
  const borderGeo = new PlaneGeometry(panelW + 0.012, panelH + 0.012);
  const border = new Mesh(borderGeo, borderMat);
  border.position.z = -0.002;
  root.add(border);

  // ── Content strata raised +0.03 above panel surface
  const content = new Group();
  content.position.z = 0.03;
  root.add(content);

  const accentHex = colors.accent ?? '#ff2a38';
  const paperHex = colors.paper ?? '#e8ecf2';
  // fontAtlas px → scene-unit scale: 62px ≡ 0.62u  ⇒ 0.01
  const S = 0.01;
  const leftMargin = -panelW / 2 + 0.5;

  function makeText(str, opts) {
    const t = ctx.fontAtlas.createText(str, opts);
    t.scale.setScalar(S);
    return t;
  }

  const mkItem = items.find(i => i.role === 'quote-mark');
  const qItem = items.find(i => i.role === 'quote');
  const aItem = items.find(i => i.role === 'attribution');
  const cItem = items.find(i => i.role === 'caption');

  const markTopY = panelH / 2 - 0.5;
  const markH = 0.62;
  const markCenterY = markTopY - markH / 2;
  const markBottomY = markTopY - markH;

  // Oversized accent quotation mark — extruded +0.04 above content layer
  let markObj = null;
  if (mkItem) {
    markObj = makeText(mkItem.text ?? '"', {
      fontSize: mkItem.typography?.fontSize ?? 62,
      color: accentHex,
      align: 'left',
      letterSpacing: mkItem.typography?.letterSpacing ?? 0,
    });
    markObj.position.set(leftMargin, markCenterY, 0.01);
    // Prefrig the weighted-settle starting point
    markObj.scale.setScalar(S * 1.04);
    content.add(markObj);
  }

  // Quote body — set 0.25u below the mark, max measure 2.4u
  let quoteObj = null;
  if (qItem) {
    quoteObj = makeText(qItem.text ?? '', {
      fontSize: qItem.typography?.fontSize ?? 20,
      color: paperHex,
      align: 'left',
      letterSpacing: qItem.typography?.letterSpacing ?? 0,
      maxWidthPx: 240,
    });
    quoteObj.position.set(leftMargin, markBottomY - 0.25, 0);
    content.add(quoteObj);
  }

  // Estimate quote wrapped height
  const quoteLineH = (qItem?.typography?.lineHeight ?? 1.45) * (qItem?.typography?.fontSize ?? 20) * S;
  const quoteText = qItem?.text ?? '';
  const charWidthFrac = 0.5;
  const pxPerLine = 240;
  const pxPerChar = (qItem?.typography?.fontSize ?? 20) * charWidthFrac;
  const charsPerLine = Math.max(5, Math.floor(pxPerLine / pxPerChar));
  const quoteLines = Math.max(1, Math.ceil(quoteText.length / charsPerLine));
  const quoteHeight = quoteLines * quoteLineH;
  const quoteBottomY = (markBottomY - 0.25) - quoteHeight;
  const attrTopY = quoteBottomY - 0.25;

  // Attribution row: accent emissive rule + name + caption
  if (aItem) {
    // 0.2w × 0.02h accent rule, emissive 1.4
    const ruleMat = new MeshStandardNodeMaterial({
      color: 0x000000,
      roughness: 0.5,
      metalness: 0.0,
    });
    ruleMat.emissiveNode = uniform(new Color(accentHex));
    ruleMat.emissiveIntensityNode = uniform(1.4);
    const ruleGeo = new PlaneGeometry(0.2, 0.02);
    const rule = new Mesh(ruleGeo, ruleMat);
    rule.position.set(leftMargin + 0.1, attrTopY - 0.013, 0.04);
    content.add(rule);

    const attrObj = makeText(aItem.text ?? '', {
      fontSize: aItem.typography?.fontSize ?? 13,
      color: paperHex,
      align: 'left',
      letterSpacing: (aItem.typography?.letterSpacing ?? 0.08) * 13,
    });
    attrObj.position.set(leftMargin + 0.34, attrTopY - 0.07, 0.02);
    content.add(attrObj);
  }

  if (cItem) {
    const attrLineH = (aItem?.typography?.lineHeight ?? 1.2) * (aItem?.typography?.fontSize ?? 13) * S;
    const captionObj = makeText(cItem.text ?? '', {
      fontSize: cItem.typography?.fontSize ?? 9,
      color: '#9a9aa3',
      align: 'left',
      letterSpacing: (cItem.typography?.letterSpacing ?? 0.12) * 9,
    });
    captionObj.position.set(leftMargin + 0.34, attrTopY - attrLineH - 0.1, 0.02);
    content.add(captionObj);
  }

  // ── Lighting: key + accent rim + ambient fill
  const key = new DirectionalLight(0xffffff, 1.0);
  key.position.set(3.2, 2.0, 4.0);
  root.add(key);

  const rim = new DirectionalLight(new Color(accentHex), 0.6);
  rim.position.set(-3.0, 1.2, 2.5);
  root.add(rim);

  const amb = new AmbientLight(0xffffff, 0.6);
  root.add(amb);

  // ── Entrance motion (no idle — the piece rests with weight)
  const fadeTimeline = gsap.timeline({ delay: 0.08 });
  fadeTimeline.fromTo(
    root.position,
    { y: 0.2 },
    { y: 0, duration: 0.5, ease: 'power2.out' }
  );

  let markSettle = null;
  if (markObj) {
    markSettle = gsap.timeline({ delay: 0.5 });
    markSettle.to(markObj.scale, {
      x: S, y: S, z: S,
      duration: 0.9,
      ease: 'power4.out',
    });
  }

  // ── Cleanup
  root.userData.cleanup = function cleanup() {
    fadeTimeline.kill();
    if (markSettle) markSettle.kill();
    root.traverse((o) => {
      if (o.geometry?.dispose) o.geometry.dispose();
      if (o.material) {
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose && m.dispose());
        else if (o.material.dispose) o.material.dispose();
      }
    });
  };

  root.userData.handlers = {};

  return root;
}
